    "sourceTitle": "Muôn đời cầu tiên",
    "description": "Muôn đời nhập phàm trần, không tranh một đời chi cảnh xuân tươi đẹp, chỉ tranh muôn đời chi sớm chiều.\n\n\nVới hồng trần trung cầu tiên.\n\n\nTa kêu Lý thanh, tam thế thoát phàm, chín thế nhập đạo, muôn đời thành tiên.\n\n\n( trường sinh lưu, phi bắt chước khí, phi chuyển thế trọng sinh )\n\n\n( muôn đời thọ nguyên, một đời sinh )",
