export function getWikiChapters(storyId) {
  const book = wikiCatalog[storyId];
  if (!book) return [];
  const prefix = storyId === 'moi-ngay-mot-que' ? 'moi-ngay' : storyId;
  return book.chapters.map(ch => ({
    id: prefix + '-chap-' + ch.chapterIndex, storyId, chapterIndex: ch.chapterIndex,
    title: ch.title, content: '', hasAudioFile: false,
    source: 'wikicv', sourceVersion: WIKI_SOURCE_VERSION,
    sourceUrl: 'https://wikicv.org' + ch.path,
  }));
}

export function isCurrentChapterSource(chapter) {
  if (!wikiCatalog[chapter.storyId]) return true;
  const expected = wikiCatalog[chapter.storyId].chapters.find(ch => ch.chapterIndex === chapter.chapterIndex);
  return !!expected && chapter.source === 'wikicv' && chapter.sourceVersion === WIKI_SOURCE_VERSION
    && chapter.sourceUrl === 'https://wikicv.org' + expected.path;
}
